function rightSideView(root) {
    const result = [];
    if (!root)
        return result;
    let queue = [root];
    while (queue.length) {
        result.push(queue[queue.length - 1].val);
        const next = [];
        for (const node of queue) {
            if (node.left)
                next.push(node.left);
            if (node.right)
                next.push(node.right);
        }
        queue = next;
    }
    return result;
}

