# 方法一：BFS 層序遍歷（推薦，最直覺）
class Solution:
    def rightSideView(self, root: Optional[TreeNode]) -> List[int]:
        if not root:
            return []
        from collections import deque

        result = []
        queue = deque([root])

        while queue:
            size = len(queue)              # 這一層的節點數
            for i in range(size):
                node = queue.popleft()
                if i == size - 1:          # 該層最後一個 = 最右邊
                    result.append(node.val)
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)

        return result


# 方法二：DFS 先右後左
class Solution:
    def rightSideView(self, root: Optional[TreeNode]) -> List[int]:
        result = []

        def dfs(node, depth):
            if not node:
                return
            # 第一次到達這個深度 → 必定是該層最右邊
            if depth == len(result):
                result.append(node.val)

            dfs(node.right, depth + 1)     # ★ 先遞迴右子樹
            dfs(node.left, depth + 1)

        dfs(root, 0)
        return result

